import math


def paginate(items: list, page: int, per_page: int) -> dict:
    total_pages = math.ceil(len(items) / per_page)
    if page < 1:
        page_items = []
    else:
        start = (page - 1) * per_page
        page_items = items[start:start + per_page]
    return {
        'items': page_items,
        'page': page,
        'total_pages': total_pages,
    }
